const ScriptOpcodeInfo* scriptOpcodeInfo(int32_t opcode) {
    if (opcode < 0 || opcode > 255) {
        return nullptr;
    }
    const ScriptOpcodeInfo& info = kInfos[opcode];
    // The opcodes that are not in the C#'s table have no operands
    // pointer, and the decoder rejects them.
    return info.operands != nullptr ? &info : nullptr;
}

